private fun column(raw: String): Map<String, String> {
    val parts = raw.split('|')
    check(parts.size == restKeys.size) {
        "Expected ${restKeys.size} phrases, found ${parts.size}"
    }
    return restKeys.zip(parts).toMap()
}

